-- Zoho suite tool classification seeds.
--
-- Generated by liftoff-connector-service scripts/classify-connector-tools.ts
-- (--from-registry) over the tool sets that
-- @liftoffos/composio-overlays@0.2.12 merges into the connector registry.
--
-- Without these rows every tool defaults fail-secure — write + sensitive +
-- destructive — which fires HITL on every single call and makes the connector
-- unusable in practice.
--
-- Only the three Zoho toolkits Composio actually serves tools for are seeded:
-- zoho (Zoho CRM, 6 tools), zoho_bigin (12) and zoho_invoice (6). zoho_books,
-- zoho_desk, zoho_inventory and zoho_mail ship coming_soon with zero callable
-- tools, so there is nothing to classify; they need their own seed if Composio
-- starts serving them and they flip to available.
--
-- ── The key is tool_name, NOT (tool_name, integration_type) ──────────────
--
-- `tool_classification_cache_pkey` (migration 081) is UNIQUE on
-- (tool_name, COALESCE(tenant_id, '__global__')), and
-- ToolClassifier.getCachedClassification looks a tool up by tool_name alone —
-- integration_type is carried for provenance and never filtered on. One row
-- therefore serves every connector that exposes a tool of that name.
--
-- That has two consequences for this migration, both handled below:
--
--   1. get_records is exposed by BOTH zoho and zoho_bigin. Listing it twice in
--      one INSERT is not "two rows", it is a 21000 —
--      "ON CONFLICT DO UPDATE command cannot affect row a second time" — which
--      aborts the whole pending batch and blocks every deploy behind it.
--      scripts/ci/verify-migrations.sh caught exactly that on the first draft.
--      It is seeded once, under zoho, and zoho_bigin's identically-named tool
--      resolves to the same row. Both are reads classified ARRAY[], so the
--      shared row is correct for both.
--
--   2. list_contacts already exists under hubspot, and list_invoices under
--      stripe and deel. Those rows are ARRAY[] reads and the Zoho tools of the
--      same name are ARRAY[] reads, so re-seeding them changes categories for
--      nobody. Checked before writing this, because the ON CONFLICT would
--      otherwise silently relax an existing connector's HITL gate.
--
-- Sharing rows by bare tool name is a property of the schema, not something
-- this change introduces — create_task, delete_event and create_contact are
-- already shared across several connectors the same way.
--
-- Deletes are 'dataChanges', matching the rest of the estate
-- (gmail_delete_email, hubspot_delete_contact, delete_calendar). Every
-- zoho_invoice tool is a read: the served set is entirely GET/LIST, so an agent
-- can report on invoices and payments but cannot raise or settle one.

INSERT INTO tool_classification_cache (tool_name, integration_type, tool_description_hash, categories, draft_variant, reviewed_by, is_manual_override, tenant_id)
VALUES
  -- zoho (Zoho CRM). get_records is seeded here and also serves zoho_bigin.
  ('get_records', 'zoho', '47f54bc8d547', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('create_record', 'zoho', '8370d9bf6fde', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('update_record', 'zoho', '09a97bfaf3e9', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('update_related_records', 'zoho', 'af7f20e7e018', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('create_tag', 'zoho', '9f71f7266b9e', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('convert_lead', 'zoho', '4492bac2129b', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),

  -- zoho_bigin (get_records omitted — seeded above under zoho, same categories)
  ('get_modules', 'zoho_bigin', 'a5b20af85eb1', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('get_deleted_records', 'zoho_bigin', 'df94552ea7e5', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('get_attachments', 'zoho_bigin', '1ae4afad21aa', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('download_attachment', 'zoho_bigin', 'b9a52c7238cc', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('add_records', 'zoho_bigin', '28afb11cae77', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('update_records', 'zoho_bigin', 'ceb0bcab064c', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('add_tags_to_records', 'zoho_bigin', '81f1da830203', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('create_tags', 'zoho_bigin', 'f8458661a4fd', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('upload_attachment', 'zoho_bigin', '1498c92acabb', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('delete_records', 'zoho_bigin', '3ce4520b3b8e', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('delete_attachment', 'zoho_bigin', '0605b8f17097', ARRAY['dataChanges']::TEXT[], NULL, 'classify-script-v1', false, NULL),

  -- zoho_invoice (served set is entirely read-only)
  ('list_invoices', 'zoho_invoice', '8afd1b7fd3f0', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('list_contacts', 'zoho_invoice', '361192062bc3', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('list_payments', 'zoho_invoice', 'a5c53fea03fb', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('list_expenses', 'zoho_invoice', '96add3097539', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
  ('list_items', 'zoho_invoice', '85882213cec7', ARRAY[]::TEXT[], NULL, 'classify-script-v1', false, NULL),
